--显示各种物品的dialog
ItemDialog = class("ItemDialog", WindowController);
ItemDialog.instance = nil;
ItemDialogView = class("ItemDialogView", WindowView)
local this = ItemDialogView;
this.callback = nil;
this.defaultConfirmText = TextSystem.GetText("confirm");

ItemDialogType =
{
    Text = 1,
    TextImage = 2,
    TextImageNumberCtrl = 3,
    ChestUnlock = 4,
};

---构造函数
function ItemDialog:ctor()
    ItemDialog.super.ctor(self);
    self.name = "ItemDialogCtrl";
end

---单例，方便外界调用
function ItemDialog.Instance()
    if ItemDialog.instance == nil then
        ItemDialog.instance = ItemDialog.new();
    end
    return ItemDialog.instance;
end

---confirmText填nil会给默认文本“确定”
function ItemDialog:Show(itemType, id, confirmButtonText, callback, itemDlgType)
    this.callback = callback;
    ItemDialogView.Show(itemType, id, 0, confirmButtonText, itemDlgType);
    self:ShowWindow();
end

function ItemDialog:ShowChestUnlockDlg(id, cost, confirmButtonText, callback)
    this.callback = callback;
    ItemDialogView.Show(ItemType.Chest, id, cost, confirmButtonText, ItemDialogType.ChestUnlock);
    self:ShowWindow();
end

function ItemDialog.ConfirmOnClick()
    if (this.callback ~= nil) then
        this.callback(true);
    end
    ItemDialog.Instance():HideWindow();
end

function ItemDialog.CancelOnClick()
    if (this.callback ~= nil) then
        this.callback(false);
    end
    ItemDialog.Instance():HideWindow();
end


---构造函数
function ItemDialogView:ctor()
    ItemDialogView.super.ctor(self);
    self.name = "ItemDialog";
end

---单例，方便外界调用
function ItemDialogView.Instance()
    if ItemDialogView.instance == nil then
        ItemDialogView.instance = ItemDialogView.new();
    end
    return ItemDialogView.instance;
end

function ItemDialogView:OnViewLoad()
    ItemDialogView.super.OnViewLoad(self);
    self:FindComponent();

    self.Init();
end

function ItemDialogView.Init()
    EventDelegate.Add(this.confirmEvent.onClick, EventDelegate.Callback(ItemDialog.ConfirmOnClick));
    EventDelegate.Add(this.cancelEvent.onClick, EventDelegate.Callback(ItemDialog.CancelOnClick));
end

function ItemDialogView.Show(itemType, id, cost, confirmButtonText, itemDlgType)
    if (itemDlgType == nil) then
        itemDlgType = ItemDialogType.TextImage;
    end

    this.numberController:SetActive(itemDlgType == ItemDialogType.TextImageNumberCtrl);

    this.itemImageSprite.spriteName = GameLogic.GetItemSpriteName(itemType, id);
    this.itemQualitySprite.spriteName = "bag_icon0" .. GameLogic.GetItemQuality(itemType, id);

    local name = GameLogic.GetItemName(itemType, id);
    local description = nil;
    if (itemDlgType == ItemDialogType.ChestUnlock) then
        description = TextSystem.GetText("consume") .. cost .. TextSystem.GetText("open_chest_describe");
    else
        description = GameLogic.GetItemDescription(itemType, id);
    end

    if (name ~= nil) then
        this.nameLabel.text = name;
    else
        this.nameLabel.text = "";
    end
    if (description ~= nil) then
        this.descLabel.text = description;
    else
        this.descLabel.text = "";
    end

    if (confirmButtonText ~= nil) then
        this.confirmLabel.text = confirmButtonText;
    else
        this.confirmLabel.text = this.defaultConfirmText;
    end
end

function ItemDialogView:FindComponent()
    this.itemImageObj = self.transform:Find("Background/ItemImage").gameObject;
    this.itemImageSprite = self.transform:Find("Background/ItemImage/Sprite"):GetComponent("UISprite");
    this.itemQualitySprite = self.transform:Find("Background/ItemImage/QualitySprite"):GetComponent("UISprite");
    this.numberController = self.transform:Find("Background/NumberController").gameObject;
    this.nameLabel = self.transform:Find("Background/NameLabel"):GetComponent("UILabel");
    this.descLabel = self.transform:Find("Background/DescriptionLabel"):GetComponent("UILabel");
    this.confirmLabel = self.transform:Find("Background/ConfirmButton/Label").gameObject:GetComponent("UILabel");

    this.confirmEvent = self.transform:Find("Background/ConfirmButton").gameObject:GetComponent("UIButton");
    this.cancelEvent = self.transform:Find("MaskBG").gameObject:GetComponent("UIEventTrigger");
end

